import gdb, os, hashlib

BIN = os.environ["CBIN"]
INFILE = os.environ["CINFILE"]

edges = set()
state = {"last": None, "steps": 0}
MAX_STEPS = 300000

gdb.execute("set pagination off")
gdb.execute("set confirm off")
gdb.execute("set breakpoint pending on")
gdb.execute("set disable-randomization on")

class StartBP(gdb.Breakpoint):
    def __init__(self):
        super().__init__("*__libc_start_main")
    def stop(self):
        try:
            main = int(gdb.parse_and_eval("$rdi"))
        except gdb.error:
            return True
        gdb.execute("delete")
        MainBP(main)
        return False

class MainBP(gdb.Breakpoint):
    def __init__(self, addr):
        super().__init__("*%d" % addr, internal=True)
    def stop(self):
        gdb.execute("delete")
        step_loop()
        return True

def step_loop():
    inf = gdb.selected_inferior()
    while state["steps"] < MAX_STEPS:
        try:
            pc = int(gdb.parse_and_eval("$pc"))
        except gdb.error:
            break
        if state["last"] is not None:
            edges.add((state["last"], pc))
        state["last"] = pc
        state["steps"] += 1
        try:
            gdb.execute("stepi", to_string=True)
        except gdb.error:
            break

gdb.execute("file %s" % BIN)
StartBP()
try:
    gdb.execute("run %s" % INFILE, to_string=True)
except gdb.error as e:
    sys_err = getattr(gdb, "error", None)
    print("RUNERR", e)

h = hashlib.sha1()
for e in sorted(edges):
    h.update(("%d,%d;" % e).encode())
print("COVHASH %s steps=%d edges=%d" % (h.hexdigest()[:16], state["steps"], len(edges)))
