        for order in [0,1,2,4]:
            res=[(i%20)-10 for i in range(bs)]
            np=1<<porder
            try:
                f=make_frame([lambda bw: sub_fixed(bw,order,[1]*order,res[order:],16,porder=porder,params=[4]*np,escape=False),
                              lambda bw: sub_fixed(bw,order,[2]*order,res[order:],16,porder=porder,params=[4]*np,escape=False)],
